// tests/media-storage.test.ts - v1.1.3 media storage abstraction

import { test } from "node:test";
import assert from "node:assert/strict";

import {
  PassthroughStorage,
  S3Storage,
  CompositeStorage,
  createMediaStorage,
} from "../src/storage/media.js";

const SAMPLE = Buffer.from("hello world");

// ===== PassthroughStorage =====

test("v1.1.3 PassthroughStorage.put — 返 vendor CDN URL (无副作用)", async () => {
  const s = new PassthroughStorage({ cdnBase: "https://wx.juhe.chat/cdn" });
  const r = await s.put("img/abc.jpg", SAMPLE, "image/jpeg");
  assert.equal(r.url, "https://wx.juhe.chat/cdn/img/abc.jpg");
  assert.equal(r.key, "img/abc.jpg");
  assert.equal(r.size, SAMPLE.length);
  assert.equal(r.storage, "passthrough");
});

test("v1.1.3 PassthroughStorage.sign — 返永久 URL", async () => {
  const s = new PassthroughStorage({ cdnBase: "https://x" });
  const url = await s.sign("img/abc.jpg", 3600);
  assert.equal(url, "https://x/img/abc.jpg");
});

test("v1.1.3 PassthroughStorage.ping — 永远 true", async () => {
  const s = new PassthroughStorage({ cdnBase: "https://x" });
  assert.equal(await s.ping(), true);
});

test("v1.1.3 PassthroughStorage — cdnBase 空 抛错", () => {
  assert.throws(() => new PassthroughStorage({ cdnBase: "" }), /cdnBase/);
});

// ===== S3Storage =====


test("v1.1.3 S3Storage.endpoint 末尾 / 自动去 (sync 检查)", () => {
  const s = new S3Storage({
    endpoint: "https://oss.com/",
    region: "r", bucket: "b", accessKeyId: "a", secretAccessKey: "s",
  });
  // 用 sign 测 publicUrl 格式 (sync, 不发网络请求)
  s.sign("img/k.jpg", 60).then((url) => {
    assert.ok(!url.includes("//img"), `path-style 不应双 /, 实际: ${url.slice(0, 80)}`);
  });
});

test("v1.1.3 S3Storage.ping — fake endpoint timeout 返 false (不挂死)", async () => {
  const s = new S3Storage({
    endpoint: "https://nonexistent.invalid",
    region: "r", bucket: "x",
    accessKeyId: "a", secretAccessKey: "s",
  });
  // 用不存在的域名, 应 3s timeout 返 false
  const start = Date.now();
  const ok = await s.ping();
  const dur = Date.now() - start;
  assert.equal(ok, false, "ping 失败应返 false");
  assert.ok(dur < 5000, `应 < 5s timeout, 实际 ${dur}ms`);
});

test("v1.1.3 S3Storage.put — fake creds (测真 SDK 调用不挂)", async () => {
  const s = new S3Storage({
    endpoint: "https://nonexistent.invalid",
    region: "r", bucket: "x",
    accessKeyId: "a", secretAccessKey: "s",
  });
  // put 会失败 (网络不可达), 但 SDK 调用不挂 (timeout)
  try {
    await s.put("k", SAMPLE, "text/plain");
    assert.fail("应 throw (网络不可达)");
  } catch (e) {
    assert.ok(e instanceof Error, "应抛 Error");
  }
});


// ===== CompositeStorage =====

test("v1.1.3 CompositeStorage — primary (passthrough) OK, 不 fallback", async () => {
  const primary = new PassthroughStorage({ cdnBase: "https://primary" });
  const fallback = new S3Storage({
    endpoint: "https://s3.amazonaws.com", region: "r", bucket: "b",
    accessKeyId: "a", secretAccessKey: "s",
  });
  const c = new CompositeStorage(primary, fallback);
  const r = await c.put("k", SAMPLE, "text/plain");
  assert.equal(r.storage, "passthrough", "primary OK 应不 fallback");
  assert.match(r.url, /primary/);
});

test("v1.1.3 CompositeStorage — primary 抛错 fallback S3 (用 fake fallback 不发网络)", async () => {
  const primary: any = {
    put: async () => { throw new Error("primary down"); },
    get: async () => { throw new Error("primary down"); },
    sign: async () => { throw new Error("primary down"); },
    ping: async () => false,
    kind: "passthrough",
  };
  // 用 fake fallback 替真 S3 (避免网络挂死)
  const fallback: any = {
    put: async (key: string, buffer: Buffer) => ({
      url: `https://fake-s3/${key}`,
      key,
      etag: "fake-etag",
      size: buffer.length,
      storage: "s3" as const,
    }),
    get: async () => { throw new Error("fake"); },
    sign: async () => "https://fake-s3/signed",
    ping: async () => true,
    kind: "s3" as const,
  };
  const c = new CompositeStorage(primary, fallback);
  const r = await c.put("k", SAMPLE, "text/plain");
  assert.equal(r.storage, "s3", "应 fallback 到 fake S3");
});

test("v1.1.3 CompositeStorage — 顺序检查 (primary 不能 s3 + fallback passthrough)", () => {
  const s3 = new S3Storage({ endpoint: "https://x", region: "r", bucket: "b", accessKeyId: "a", secretAccessKey: "s" });
  const p = new PassthroughStorage({ cdnBase: "https://x" });
  assert.throws(
    () => new CompositeStorage(s3, p),
    /CompositeStorage: primary 不能是 s3 \+ fallback passthrough/,
  );
});

// ===== factory =====

test("v1.1.3 createMediaStorage — passthrough", () => {
  const s = createMediaStorage({ kind: "passthrough", passthrough: { cdnBase: "https://x" } });
  assert.equal(s.kind, "passthrough");
});

test("v1.1.3 createMediaStorage — s3", () => {
  const s = createMediaStorage({
    kind: "s3",
    s3: { endpoint: "https://x", region: "r", bucket: "b", accessKeyId: "a", secretAccessKey: "s" },
  });
  assert.equal(s.kind, "s3");
});

test("v1.1.3 createMediaStorage — composite (passthrough primary + s3 fallback)", () => {
  const s = createMediaStorage({
    kind: "composite",
    composite: {
      primaryKind: "passthrough",
      cdnBase: "https://primary",
      s3: { endpoint: "https://s3", region: "r", bucket: "b", accessKeyId: "a", secretAccessKey: "s" },
    },
  });
  assert.equal(s.kind, "composite");
});

test("v1.1.3 createMediaStorage — 缺 config 抛错", () => {
  assert.throws(() => createMediaStorage({ kind: "passthrough" } as any), /cdnBase/);
  assert.throws(() => createMediaStorage({ kind: "s3" } as any), /s3 config/);
});

// src/storage/media.ts - 媒体存储抽象 (S3-compatible interface + vendor CDN fallback)
// @aws-sdk/client-s3 完整 S3 API + s3-request-presigner presigned URL;
// 兼容 AWS S3 / MinIO / AliOSS / TXOSS / Cloudflare R2 (path-style 配置)
//
// 用途: 解决 vendor CDN 不稳定时 (高并发限流, 临时不可用) 媒体 (图片/语音/视频) 备份
// 设计:
//   - MediaStorage 抽象接口 (S3-compatible: put/get/sign/url)
//   - PassthroughStorage: 直接返回 vendor 给的 URL (默认, 无副作用)
//   - S3Storage: 用 @aws-sdk 完整 putObject + presigned URL
//   - CompositeStorage: 优先 vendor CDN, 失败 fallback S3 (高可用)
//
// 调用方约定:
//   - storage.put(key, buffer, mimeType) → 返回 { url, etag, ... }
//   - storage.get(key) → 返 buffer
//   - storage.sign(key, expiresIn) → 返 presigned URL (S3 模式) 或 直传 URL (vendor 模式)

import { S3Client, PutObjectCommand, GetObjectCommand, HeadBucketCommand } from "@aws-sdk/client-s3";
import { getSignedUrl } from "@aws-sdk/s3-request-presigner";
import { logObj as log } from "../core/logger.js";

export type StorageKind = "passthrough" | "s3" | "composite";

export interface MediaPutResult {
  url: string;        // 公开访问 URL
  key: string;        // storage key
  etag?: string;      // ETag (S3 模式)
  size: number;       // bytes
  storage: StorageKind;
}

export interface MediaGetResult {
  buffer: Buffer;
  mimeType: string;
  storage: StorageKind;
}

export interface MediaStorage {
  readonly kind: StorageKind;
  put(key: string, buffer: Buffer, mimeType: string): Promise<MediaPutResult>;
  get(key: string): Promise<MediaGetResult>;
  sign(key: string, expiresInSec: number): Promise<string>;
  /** 健康检查 (测试用) */
  ping(): Promise<boolean>;
}

// ============ PassthroughStorage (vendor CDN 直传) ============

/** PassthroughStorage 不存, 返原 URL (vendor 已有 CDN) */
export class PassthroughStorage implements MediaStorage {
  readonly kind = "passthrough" as const;

  constructor(private options: { cdnBase: string }) {
    if (!options.cdnBase) {
      throw new Error("PassthroughStorage requires cdnBase (e.g. https://your-cdn.example.com/cdn)");
    }
  }

  async put(key: string, buffer: Buffer, _mimeType: string): Promise<MediaPutResult> {
    return {
      url: `${this.options.cdnBase}/${key}`,
      key,
      size: buffer.length,
      storage: this.kind,
    };
  }

  async get(_key: string): Promise<MediaGetResult> {
    throw new Error("PassthroughStorage.get: 不支持, 直接用 vendor CDN URL");
  }

  async sign(key: string, _expiresInSec: number): Promise<string> {
    return `${this.options.cdnBase}/${key}`;
  }

  async ping(): Promise<boolean> {
    return true;
  }
}

// ============ S3Storage (真实 S3 集成) ============

export interface S3Config {
  endpoint: string;       // https://s3.amazonaws.com 或 https://oss-cn-hangzhou.aliyuncs.com
  region: string;
  bucket: string;
  accessKeyId: string;
  secretAccessKey: string;
  /** 是否用 path-style URL (MinIO/部分 OSS 需要) */
  pathStyle?: boolean;
  /** CDN 域名 (返 URL 用, 比 endpoint 直链快) */
  cdnBase?: string;
}

/**
 * @aws-sdk/client-s3 + s3-request-presigner
 * 兼容: AWS S3 / MinIO / AliOSS / TXOSS / Cloudflare R2
 */
export class S3Storage implements MediaStorage {
  readonly kind = "s3" as const;
  private readonly client: S3Client;
  private readonly endpoint: string;
  private readonly cdnBase: string | undefined;

  constructor(private config: S3Config) {
    if (!config.endpoint || !config.bucket) {
      throw new Error("S3Storage requires endpoint + bucket");
    }
    this.endpoint = config.endpoint.replace(/\/$/, "");
    this.cdnBase = config.cdnBase?.replace(/\/$/, "");
    this.client = new S3Client({
      endpoint: this.endpoint,
      region: config.region || "us-east-1",
      credentials: {
        accessKeyId: config.accessKeyId,
        secretAccessKey: config.secretAccessKey,
      },
      forcePathStyle: config.pathStyle ?? false,
    });
  }

  async put(key: string, buffer: Buffer, mimeType: string): Promise<MediaPutResult> {
    const cmd = new PutObjectCommand({
      Bucket: this.config.bucket,
      Key: key,
      Body: buffer,
      ContentType: mimeType,
    });
    // put/get 加 30s timeout 防 endpoint 挂死时消息队列无限积压
    const resp = await this.withTimeout(this.client.send(cmd), 30_000, `put ${key}`);
    return {
      url: this.publicUrl(key),
      key,
      etag: resp.ETag,
      size: buffer.length,
      storage: this.kind,
    };
  }

  async get(key: string): Promise<MediaGetResult> {
    const cmd = new GetObjectCommand({ Bucket: this.config.bucket, Key: key });
    const resp = await this.withTimeout(this.client.send(cmd), 30_000, `get ${key}`);
    if (!resp.Body) throw new Error(`S3Storage.get: empty body for ${key}`);
    const bytes = await this.withTimeout(resp.Body.transformToByteArray(), 60_000, `get-body ${key}`);
    return {
      buffer: Buffer.from(bytes),
      mimeType: resp.ContentType ?? "application/octet-stream",
      storage: this.kind,
    };
  }

  /**
   * 30s timeout race wrapper for any S3 op.
   * AbortController is the cleanest path but @aws-sdk v3 default config has requestHandler; for simplicity use Promise.race.
   */
  private async withTimeout<T>(p: Promise<T>, ms: number, label: string): Promise<T> {
    let timer: NodeJS.Timeout | undefined;
    try {
      return await Promise.race([
        p,
        new Promise<T>((_, reject) => {
          timer = setTimeout(() => reject(new Error(`S3Storage: ${label} timeout after ${ms}ms`)), ms);
          timer.unref?.();
        }),
      ]);
    } finally {
      if (timer) clearTimeout(timer);
    }
  }

  async sign(key: string, expiresInSec: number): Promise<string> {
    const cmd = new GetObjectCommand({ Bucket: this.config.bucket, Key: key });
    return getSignedUrl(this.client, cmd, { expiresIn: expiresInSec });
  }

  async ping(): Promise<boolean> {
    // 加 timeout (防网络挂死)
    try {
      const cmd = new HeadBucketCommand({ Bucket: this.config.bucket });
      await Promise.race([
        this.client.send(cmd),
        new Promise<never>((_, reject) => setTimeout(() => reject(new Error("ping timeout")), 3000)),
      ]);
      return true;
    } catch {
      return false;
    }
  }

  /** 公共 URL (virtual-hosted or path-style) */
  private publicUrl(key: string): string {
    if (this.cdnBase) return `${this.cdnBase}/${key}`;
    if (this.config.pathStyle) {
      return `${this.endpoint}/${this.config.bucket}/${key}`;
    }
    // virtual-hosted: {bucket}.{endpoint}/{key}
    const u = new URL(this.endpoint);
    return `${u.protocol}//${this.config.bucket}.${u.host}/${key}`;
  }
}

// ============ CompositeStorage (vendor CDN + S3 fallback) ============

/** 优先用 vendor CDN (passthrough), 失败时 fallback S3 */
export class CompositeStorage implements MediaStorage {
  readonly kind = "composite" as const;

  constructor(
    private primary: MediaStorage,
    private fallback: MediaStorage,
  ) {
    if (primary.kind === "s3" && fallback.kind === "passthrough") {
      throw new Error("CompositeStorage: primary 不能是 s3 + fallback passthrough (无意义)");
    }
  }

  async put(key: string, buffer: Buffer, mimeType: string): Promise<MediaPutResult> {
    try {
      return await this.primary.put(key, buffer, mimeType);
    } catch (e) {
      log.warn(`CompositeStorage.put primary(${this.primary.kind}) failed: ${e}, fallback to ${this.fallback.kind}`);
      return await this.fallback.put(key, buffer, mimeType);
    }
  }

  async get(key: string): Promise<MediaGetResult> {
    try {
      return await this.primary.get(key);
    } catch (e) {
      log.warn(`CompositeStorage.get primary failed: ${e}, fallback`);
      return await this.fallback.get(key);
    }
  }

  async sign(key: string, expiresInSec: number): Promise<string> {
    return this.primary.sign(key, expiresInSec);
  }

  async ping(): Promise<boolean> {
    const a = await this.primary.ping();
    if (a) return true;
    return this.fallback.ping();
  }
}

// ============ factory ============

export function createMediaStorage(config: {
  kind: StorageKind;
  passthrough?: { cdnBase: string };
  s3?: S3Config;
  composite?: { primaryKind: "passthrough" | "s3"; s3?: S3Config; cdnBase?: string };
}): MediaStorage {
  switch (config.kind) {
    case "passthrough":
      if (!config.passthrough?.cdnBase) throw new Error("passthrough requires cdnBase");
      return new PassthroughStorage(config.passthrough);
    case "s3":
      if (!config.s3) throw new Error("s3 requires s3 config");
      return new S3Storage(config.s3);
    case "composite":
      if (!config.composite) throw new Error("composite requires composite config");
      const primary = config.composite.primaryKind === "passthrough"
        ? new PassthroughStorage({ cdnBase: config.composite.cdnBase! })
        : new S3Storage(config.composite.s3!);
      const fallback = config.composite.primaryKind === "passthrough"
        ? new S3Storage(config.composite.s3!)
        : new PassthroughStorage({ cdnBase: config.composite.cdnBase! });
      return new CompositeStorage(primary, fallback);
  }
}

// core/logger.ts - 仿 pino 接口日志 (兼容现有 log.info 调用 + 新代码函数式 info/warn/error)
// 范式仿 本项目/src/core/logger.ts
// 关键: formatErr 自动保留 stack (silent killer 永久救回)

import { PLUGIN_VERSION } from "./constants.js";

const LOG_TAG = `[WPP v${PLUGIN_VERSION}]`;

/**
 * formatErr — Error 实例保留 stack; 非 Error 实例走 String()
 * silent killer 永久救回: 之前 18+ 处只打 e.message 漏 stack, prod 难定位
 */
export function formatErr(err: unknown): string {
  if (err instanceof Error) {
    if (err.stack) return `${err.name}: ${err.message}\n${err.stack}`;
    return `${err.name}: ${err.message}`;
  }
  if (err === null || err === undefined) return String(err);
  if (typeof err === "string") return err;
  try {
    return JSON.stringify(err);
  } catch {
    return String(err);
  }
}

type Level = "INFO" | "WARN" | "ERROR" | "DEBUG";
type Fields = Record<string, unknown>;

function fmtValue(v: unknown): string {
  if (typeof v === "string") {
    return /[\s,=]/.test(v) ? JSON.stringify(v) : v;
  }
  if (v === null || v === undefined) return String(v);
  if (typeof v === "number" || typeof v === "boolean") return String(v);
  if (v instanceof Error) {
    return `"${formatErr(v).replace(/"/g, '\\"').replace(/\n/g, "\\n")}"`;
  }
  try {
    return JSON.stringify(v) ?? "null";
  } catch {
    return String(v);
  }
}

function fmtFields(fields?: Fields): string {
  if (!fields) return "";
  const parts: string[] = [];
  for (const [k, v] of Object.entries(fields)) {
    if (v === undefined) continue;
    parts.push(`${k}=${fmtValue(v)}`);
  }
  return parts.length ? " " + parts.join(" ") : "";
}

function emit(level: Level, msg: string, fields?: Fields): void {
  const line = `${new Date().toISOString()} ${level} ${LOG_TAG} ${msg}${fmtFields(fields)}`;
  if (level === "ERROR") console.error(line);
  else if (level === "WARN") console.warn(line);
  // eslint-disable-next-line no-console -- 中心 logger INFO/DEBUG 必需
  else console.log(line);
}

/**
 * Normalize fields-or-error arg into Fields record.
 * Error instances → { err: "<formatErr>" }, primitives → { value: v }
 */
function normalize(arg: unknown): Fields | undefined {
  if (arg === undefined) return undefined;
  if (arg instanceof Error) return { err: formatErr(arg) };
  if (typeof arg === "object" && arg !== null) return arg as Fields;
  return { value: arg };
}

// ============ 函数式 (本项目 风格 — 新代码推荐) ============

export function info(msg: string, fieldsOrErr?: Fields | unknown): void {
  emit("INFO", msg, normalize(fieldsOrErr));
}

export function warn(msg: string, fieldsOrErr?: Fields | unknown): void {
  emit("WARN", msg, normalize(fieldsOrErr));
}

export function error(msg: string, err?: unknown): void {
  emit("ERROR", msg, normalize(err));
}

export function debug(msg: string, fields?: Fields): void {
  if (process.env.WPP_DEBUG !== "1") return;
  emit("DEBUG", msg, fields);
}

// ============ 对象式 (兼容现有 log.info/warn/error/debug 调用) ============

function objectStyle(level: Level) {
  return (msg: string, fieldsOrErr?: Fields | unknown) => {
    emit(level, msg, normalize(fieldsOrErr));
  };
}

export const logObj = {
  info: objectStyle("INFO"),
  warn: objectStyle("WARN"),
  error: objectStyle("ERROR"),
  debug: objectStyle("DEBUG"),
} as const;

/** 默认 export = logObj 对象 (兼容 `import log from ...; log.info(...)`) */
export default logObj;

// core/constants.ts - 全局常量 SSOT

export const CHANNEL_ID = "wechatpadpro";
export const PLUGIN_NAME = "wechatpadpro";
export const PLUGIN_VERSION = "1.3.60";

// 默认 bot 昵称 (群 @ 触发检测用; accounts/<id>.json nickname 优先, 配置驱动 + 默认兜底)
export const DEFAULT_BOT_NICKNAME = "YourBot";

// 单账号 demo 默认账号 ID (B 方案 accounts/<id>.json)
export const DEFAULT_ACCOUNT_ID = "default";

// 默认 vendor upstream base
// vendor: WeChatPadPro 服务端 (adminmaxapi), 本机 fallback: http://127.0.0.1:8062
export const DEFAULT_VENDOR_API_BASE = "http://127.0.0.1:8062";

// WebSocket 路径 (vendor /ws/sync)
export const WS_PATH = "/ws/sync";

// 消息类型枚举 (vendor 定义, 见 swagger.json definitions)
export const MsgType = {
  TEXT: 1,
  IMAGE: 3,
  VOICE: 34,
  VIDEO: 43,
  EMOJI: 47,
  LOCATION: 48,
  APP: 49,
  CARD: 42,
  SYSTEM: 10000,
  REVOKE: 10002,
} as const;
export type MsgTypeValue = (typeof MsgType)[keyof typeof MsgType];

export const PeerKind = {
  DIRECT: "direct",
  GROUP: "group",
} as const;
export type PeerKindValue = (typeof PeerKind)[keyof typeof PeerKind];

// 日志 tag
export const LOG_TAG = `[WPP ${PLUGIN_VERSION}]`;

// 默认 webhook 端口/路径 (avoid 4399/4398 跟其它 plugin 冲突)
// v1.2.1 P1-fix (安全): 默认 127.0.0.1 仅本机监听, 防 0.0.0.0 全网卡暴露 → 伪造 webhook prompt injection
export const DEFAULT_WEBHOOK_HOST = "127.0.0.1";
export const DEFAULT_WEBHOOK_PORT = 4398;
export const DEFAULT_WEBHOOK_PATH = "/wechatpadpro/webhook";

// 默认 debounce 毫秒 (跟 本项目 一致)
export const DEFAULT_DEBOUNCE_MS = 1500;

// 30 分钟 in-memory dedupe TTL (标准值)
export const DEDUPE_TTL_MS = 30 * 60 * 1000;
export const REQUEST_TIMEOUT_MS = 30_000;
// webhook body size 10 MB hard cap (标准值)
export const WEBHOOK_BODY_LIMIT_BYTES = 10 * 1024 * 1024;
// API HTTP timeout 30s (标准值)
export const API_TIMEOUT_MS = 30_000;
// API retries 3 次
export const API_MAX_RETRIES = 3;
// v1.3.59 P2: JSON 响应体字节 cap (媒体端点经此下载 base64, 防巨型响应 OOM; 30MB 够图片/小文件)
export const API_JSON_MAX_BYTES = 30 * 1024 * 1024;
// vendor basePath 是 /api
export const VENDOR_BASE_PATH = "/api";

// API 重试间隔 (exp backoff, base 500ms)
export const API_RETRY_BASE_MS = 500;

// vendor MCP 服务 (v1.2.0 新增 — 老板 2026-08-09 发现 vendor 提供 MCP 端点)
// 端点: vendor 容器内 127.0.0.1:8062/mcp (beego mcp_enabled=true)
// 鉴权: Authorization: Bearer <token> (实测 = WECHATPRO_AUTHCODE, 非 TokenKey)
export const MCP_BASE_URL = "http://127.0.0.1:8062/mcp";
/** MCP 鉴权 token 的环境变量名 (复用 WECHATPRO_AUTHCODE, 凭证单一来源铁律) */
export const MCP_AUTH_TOKEN_ENV = "WECHATPRO_AUTHCODE";
/** MCP 调用超时 (5s, vendor 本地反代快) */
